scripts.酒客对话.txt:
// 和石塘镇酒馆酒客的对话

	If ($Event == 280) @Event280;
	If ($Event == 290) @Event290300;
	If ($Event == 300) @Event290300;
	If ($Event == 320) @Event320;
	If ($Event == 360) @Event360;

	Say("酒客：我们这里就数李三爬山最厉害了，华山没有他没到过的地方，听说他和华山剑派的顾枫顾大侠还有些交情呢。", 0);
	Return;

@Event280:
	Say("酒客：我们这里就数李三爬山最厉害了，华山没有他没到过的地方，听说他和华山剑派的顾枫顾大侠还有些交情呢。", 0);
	Return;
	

@Event290300:
	Say("酒客：那李三是个好人，就是有点倔脾气，爱用拳头解决事情，因此得罪了不少权贵。", 0);
	Return;
	
@Event320:
	Say("酒客：李三，你又要上山吗？", 0);
	Return;	
	
@Event360:	
	Say("酒客：唉，顾枫顾大侠死得真冤哪，竟然死在自己师弟手上。", 0);
	Return;

