scripts.张琳心对话.txt:
// 与张琳心的同伴对话

	If ($Event == 280) @Event280;
	If ($Event == 290) @Event290;
	If ($Event == 300) @Event300;
	If ($Event == 310) @Event310;
	If ($Event == 320) @Event320;
	If ($Event == 360) @Event360;

	Return;

@Event280:
	Say("张琳心：乡野酒家倒也别有一番韵致。", 21);
	Return;
	
@Event290:
	Say("张琳心：我们问问老板和酒客吧，看看他们知不知道上华山的其他办法。", 21);
	Return;
	
@Event300:
	Say("张琳心：我们快去长安找李三吧。", 21);
	Return;		
	
@Event310:
	Say("张琳心：我们快去找李三吧！", 21);
	Return;	
	
@Event320:
	Say("张琳心：事不宜迟，我们赶快上山，再晚可能就来不及了。", 21);
	Return; 	
	
@Event360:
	Say("张琳心：我们快点去长安吧。", 21);
	Return;

scripts.酒店老板对话.txt:
// 和石塘镇酒馆老板的对话

	Say("酒馆老板：二位远道而来吗？要不要坐下歇歇，喝杯水酒？", 0);
	Say("独孤剑：不必了，我们有急事在身。", 2);
	Return;

